"use client";

import { useEffect, useState } from "react";
import { listar, type Pagina } from "./api";
import { FormularioAvaliacao } from "./formulario";
import { MensagemErro } from "./mensagem-erro";

const dateFormat = new Intl.DateTimeFormat("pt-BR", { dateStyle: "short", timeZone: "America/Sao_Paulo" });

export function Avaliacoes({ podeCadastrar, emailAvaliador }: {
  podeCadastrar: boolean;
  emailAvaliador?: string;
}) {
  const [pagina, setPagina] = useState(0);
  const [revisao, setRevisao] = useState(0);
  const [dados, setDados] = useState<Pagina | null>(null);
  const [erro, setErro] = useState<Error | null>(null);

  useEffect(() => {
    const controller = new AbortController();
    listar(pagina, controller.signal)
      .then(setDados)
      .catch((error: Error) => {
        if (!controller.signal.aborted) setErro(error);
      });
    return () => controller.abort();
  }, [pagina, revisao]);

  function carregar(indice: number) {
    setDados(null);
    setErro(null);
    setPagina(indice);
    setRevisao((valor) => valor + 1);
  }

  return (
    <div className={podeCadastrar ? "dashboard with-form" : "dashboard"}>
      <section className="panel history" aria-labelledby="historico">
        <div className="panel-heading">
          <h2 id="historico">Histórico</h2>
          {dados && <span className="count">{dados.total} {dados.total === 1 ? "avaliação" : "avaliações"}</span>}
        </div>
        {erro ? (
          <div className="panel-body">
            <MensagemErro erro={erro} />
            <button type="button" className="button quiet" onClick={() => carregar(pagina)}>Tentar novamente</button>
          </div>
        ) : !dados ? (
          <p className="panel-body muted" role="status">Carregando avaliações…</p>
        ) : dados.itens.length === 0 ? (
          <p className="panel-body muted">Nenhuma avaliação cadastrada.</p>
        ) : (
          <div className="table-scroll" tabIndex={0} role="region" aria-label="Tabela de avaliações">
            <table>
              <thead>
                <tr><th scope="col">Avaliado</th><th scope="col">Comentário</th><th scope="col">Nota</th><th scope="col">Data</th></tr>
              </thead>
              <tbody>
                {dados.itens.map((item) => (
                  <tr key={item.id}>
                    <td><strong>{item.emailAvaliado}</strong><small>Por {item.emailAvaliador}</small></td>
                    <td className="comment">{item.comentarios}</td>
                    <td><span className="score">{item.nota}<small>/10</small></span></td>
                    <td className="date"><time dateTime={item.dataAvaliacao}>{dateFormat.format(new Date(item.dataAvaliacao))}</time></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
        {dados && dados.totalPaginas > 1 && (
          <nav className="pagination" aria-label="Paginação do histórico">
            <button type="button" className="button quiet" disabled={pagina === 0} onClick={() => carregar(pagina - 1)}>Anterior</button>
            <span>Página {pagina + 1} de {dados.totalPaginas}</span>
            <button type="button" className="button quiet" disabled={pagina + 1 >= dados.totalPaginas} onClick={() => carregar(pagina + 1)}>Próxima</button>
          </nav>
        )}
      </section>
      {podeCadastrar && (
        <FormularioAvaliacao emailAvaliador={emailAvaliador} onSaved={() => carregar(0)} />
      )}
    </div>
  );
}
